pub struct Store {
    items: Vec<String>,
}

impl Store {
    pub fn new() -> Self {
        Store { items: Vec::new() }
    }
    pub fn add(&mut self, s: &str) {
        self.items.push(s.to_string());
    }
    pub fn remove(&mut self, s: &str) -> bool {
        let before = self.items.len();
        self.items.retain(|i| i != s);
        before != self.items.len()
    }
    pub fn len(&self) -> usize {
        self.items.len()
    }
}

